section.code:
{
  "$schema": "https://json-schema.org/draft/2020-12/schema",
  "$id": "https://faion.net/schemas/rust-ownership-decision.json",
  "type": "object",
  "required": ["function", "answers", "signature", "version", "last_reviewed"],
  "properties": {
    "function": {"type": "string", "description": "module path + fn name"},
    "answers": {
      "type": "object",
      "required": ["keeps_value", "modifies_value", "shares_across_threads"],
      "properties": {
        "keeps_value":           {"type": "boolean"},
        "modifies_value":        {"type": "boolean"},
        "shares_across_threads": {"type": "boolean"}
      }
    },
    "signature": {
      "type": "object",
      "required": ["param_kind"],
      "properties": {
        "param_kind": {"enum": ["owned", "shared-ref", "mutable-ref", "rc", "arc", "arc-mutex"]},
        "lifetime":   {"type": "string", "pattern": "^('[a-z_]+|elided)$"}
      }
    },
    "crate_audit": {
      "type": "object",
      "description": "Crate-level result of templates/audit-clones.sh.",
      "required": ["audited", "clone_count", "rc_refcell_in_multi_thread"],
      "properties": {
        "audited":                    {"type": "boolean", "const": true},
        "clone_count":                {"type": "integer", "minimum": 0},
        "rc_refcell_in_multi_thread": {"type": "boolean", "const": false}
      }
    },
    "version":       {"type": "string", "pattern": "^\\d+\\.\\d+\\.\\d+$"},
    "last_reviewed": {"type": "string", "format": "date"}
  }
}
